def solve(text: str) -> str:
    data = text.split()
    a = int(data[0])
    b = int(data[1])

    # losing positions (P-positions): (floor(n*phi), floor(n*phi^2)),
    # in either pile order.
    loses = set()
    n = 0
    limit = max(a, b)
    while True:
        x = (n * (1 + 5 ** 0.5)) / 2.0
        xi = int(x)
        yi = xi + n
        if xi > limit:
            break
        if n > 0 and xi >= 1:
            loses.add((xi, yi))
            loses.add((yi, xi))
        n += 1

    if (a, b) in loses:
        return 'LOSE'

    for i in range(0, a + 1):
        for j in range(0, b + 1):
            if i == 0 and j == 0:
                continue
            if (i == 0) != (j == 0):
                pass
            elif i != j:
                continue
            if (a - i, b - j) in loses:
                return 'WIN %d %d' % (i, j)
    return 'LOSE'
